// SlipIQ / First Set Lab Blind Confidence Backtest V1
//
// Reads the same API-Tennis historical V3 CSV rows generated by
// scripts/backtest-first-set-lab-v3.mjs and tests whether a pre-match
// confidence score improves ROI, drawdown, and signal quality.
//
// This script does not use Supabase. It is designed for GitHub Actions.
// It uses only pre-result fields already present in the generated CSV rows.

import fs from 'node:fs';
import path from 'node:path';

const csvListRaw = process.env.CONFIDENCE_SIM_CSVS;
const outputDir = process.env.CONFIDENCE_OUTPUT_DIR ?? 'artifacts/confidence-backtest';
const modelModeFilter = process.env.CONFIDENCE_MODEL_MODE ?? 'independent';
const maxPlaysPerDay = Number(process.env.CONFIDENCE_MAX_PLAYS_PER_DAY ?? 5);
const stakeUnits = Number(process.env.CONFIDENCE_STAKE_UNITS ?? 1);
const bankrollStart = Number(process.env.CONFIDENCE_BANKROLL_START ?? 100);
const onePickPerMatch = process.env.CONFIDENCE_ONE_PICK_PER_MATCH !== '0';
const blockTiebreak = process.env.CONFIDENCE_BLOCK_TIEBREAK !== '0';
const minProbability = Number(process.env.CONFIDENCE_MIN_PROBABILITY ?? 0.03);
const minExpectedValue = Number(process.env.CONFIDENCE_MIN_EV ?? 0);
const minEdge = Number(process.env.CONFIDENCE_MIN_EDGE ?? 0);
const auditSampleSize = Number(process.env.CONFIDENCE_AUDIT_SAMPLE_SIZE ?? 75);

if (!csvListRaw) {
  console.error('Missing CONFIDENCE_SIM_CSVS. Provide comma-separated V3 row CSV paths.');
  process.exit(1);
}

function parseCsv(text) {
  const rows = [];
  let current = '';
  let row = [];
  let inQuotes = false;

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];
    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i += 1;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      row.push(current);
      current = '';
    } else if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') i += 1;
      row.push(current);
      if (row.some((cell) => cell !== '')) rows.push(row);
      row = [];
      current = '';
    } else {
      current += char;
    }
  }

  if (current || row.length) {
    row.push(current);
    rows.push(row);
  }

  const [headers, ...data] = rows;
  return data.map((cells) => Object.fromEntries(headers.map((header, index) => [header, cells[index] ?? ''])));
}

function toNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function toBool(value) {
  return String(value).toLowerCase() === 'true';
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function normalizeRows(rawRows, sourceFile) {
  return rawRows.map((row) => ({
    ...row,
    source_file: sourceFile,
    model_mode: row.model_mode || 'unknown',
    event_key: String(row.event_key ?? ''),
    event_date: String(row.event_date ?? ''),
    match: row.match || '',
    tournament: row.tournament || '',
    tournament_round: row.tournament_round || '',
    surface: row.surface || 'unknown',
    score: row.score || '',
    score_family: row.score_family || 'unknown',
    odds_bucket: row.odds_bucket || 'unknown',
    tournament_level: row.tournament_level || 'unknown',
    match_type: row.match_type || 'unknown',
    model_probability: toNumber(row.model_probability),
    bookmaker_odds: toNumber(row.bookmaker_odds),
    edge: toNumber(row.edge),
    expected_value: toNumber(row.expected_value),
    won: toBool(row.won),
    setfox_passed_default: toBool(row.setfox_passed_default),
  })).filter((row) => row.event_key && row.event_date && row.score && row.bookmaker_odds > 1 && row.model_probability > 0);
}

function loadRows(csvPaths) {
  const rows = [];
  for (const csvPath of csvPaths) {
    const text = fs.readFileSync(csvPath, 'utf8');
    rows.push(...normalizeRows(parseCsv(text), path.basename(csvPath)));
  }

  const dedupe = new Map();
  for (const row of rows) {
    const key = [row.model_mode, row.event_key, row.score, row.bookmaker_odds, row.source_file].join('|');
    dedupe.set(key, row);
  }

  return [...dedupe.values()].sort((a, b) => String(a.event_date).localeCompare(String(b.event_date)) || a.event_key.localeCompare(b.event_key));
}

function profit(row) {
  return row.won ? (row.bookmaker_odds - 1) * stakeUnits : -1 * stakeUnits;
}

function breakEvenPct(row) {
  return row.bookmaker_odds > 0 ? 1 / row.bookmaker_odds : 0;
}

function longestLosingStreak(bets) {
  let current = 0;
  let max = 0;
  for (const bet of bets) {
    if (bet.won) current = 0;
    else {
      current += 1;
      max = Math.max(max, current);
    }
  }
  return max;
}

function drawdownFromDaily(dailyRows) {
  let bankroll = bankrollStart;
  let peak = bankrollStart;
  let maxDrawdown = 0;
  const curve = [];

  for (const row of dailyRows) {
    bankroll += row.profit_units;
    peak = Math.max(peak, bankroll);
    const drawdown = peak - bankroll;
    maxDrawdown = Math.max(maxDrawdown, drawdown);
    curve.push({ ...row, bankroll, drawdown_units: drawdown });
  }

  return { max_drawdown_units: maxDrawdown, ending_bankroll: bankroll, curve };
}

function confidenceScore(row) {
  // All inputs are pre-result fields. This is intentionally simple and auditable.
  const evPoints = clamp(row.expected_value * 35, -15, 25);
  const edgePoints = clamp(row.edge * 150, -12, 22);
  const probabilityPoints = clamp((row.model_probability - minProbability) * 220, -6, 16);

  const oddsPoints = (() => {
    const odds = row.bookmaker_odds;
    if (odds >= 5 && odds < 8) return 10;
    if (odds >= 8 && odds < 12) return 7;
    if (odds >= 3 && odds < 5) return 5;
    if (odds >= 12 && odds < 18) return 3;
    if (odds >= 18 && odds < 30) return -5;
    if (odds >= 30) return -12;
    return -4;
  })();

  const familyPoints = (() => {
    if (row.score_family === 'normal') return 8;
    if (row.score_family === 'close') return 5;
    if (row.score_family === 'clear') return 3;
    if (row.score_family === 'blowout') return -7;
    if (row.score_family === 'tiebreak') return -20;
    return 0;
  })();

  const levelPoints = (() => {
    if (row.tournament_level === 'slam') return 6;
    if (row.tournament_level === 'tour_premium') return 4;
    if (row.tournament_level === 'tour_other') return 3;
    if (row.tournament_level === 'challenger') return 1;
    if (row.tournament_level === 'itf') return -5;
    return 0;
  })();

  const matchTypePoints = row.match_type === 'singles' ? 6 : -20;
  const setfoxPoints = row.setfox_passed_default ? 8 : 0;
  const surfacePoints = row.surface === 'grass' || row.surface === 'indoor' ? 2 : 0;

  const raw = 50
    + evPoints
    + edgePoints
    + probabilityPoints
    + oddsPoints
    + familyPoints
    + levelPoints
    + matchTypePoints
    + setfoxPoints
    + surfacePoints;

  return Math.round(clamp(raw, 0, 100));
}

function confidenceBucket(score) {
  if (score >= 90) return '90_100_quant_grade';
  if (score >= 80) return '80_89_s_confidence';
  if (score >= 70) return '70_79_a_confidence';
  if (score >= 60) return '60_69_watchlist';
  return '00_59_research_only';
}

function gradeLabel(score) {
  if (score >= 90) return 'Quant Grade';
  if (score >= 80) return 'S Confidence';
  if (score >= 70) return 'A Confidence';
  if (score >= 60) return 'Watchlist';
  return 'Research Only';
}

function suggestedStakeUnits(score) {
  if (score >= 90) return 1;
  if (score >= 80) return 0.75;
  if (score >= 70) return 0.5;
  if (score >= 60) return 0.25;
  return 0;
}

function volatilityLabel(row) {
  if (row.bookmaker_odds >= 12) return 'Extreme';
  if (row.bookmaker_odds >= 8) return 'Very High';
  if (row.bookmaker_odds >= 5) return 'High';
  return 'Medium';
}

function baseCandidate(row) {
  if (row.match_type !== 'singles') return false;
  if (blockTiebreak && row.score_family === 'tiebreak') return false;
  if (row.model_probability < minProbability) return false;
  if (row.expected_value < minExpectedValue) return false;
  if (row.edge < minEdge) return false;
  return true;
}

const strategyPools = [
  {
    id: 'confidence_price_pool',
    label: 'Confidence Price Pool',
    description: 'All singles, non-tiebreak, positive EV/edge exact-score candidates scored by Confidence V1.',
    rule: baseCandidate,
  },
  {
    id: 'confidence_setfox_strict',
    label: 'Confidence SetFox Strict',
    description: 'Rows that passed the frozen SetFox default rule, then ranked by Confidence V1.',
    rule: (row) => row.setfox_passed_default && baseCandidate(row),
  },
  {
    id: 'confidence_score_hunter_candidate',
    label: 'Confidence Score Hunter Candidate',
    description: 'Legacy score hunter style pool: grass flag, odds 5-8, tour_other, positive EV/edge, scored by Confidence V1.',
    rule: (row) => row.surface === 'grass' && row.odds_bucket === 'odds_5_8' && row.tournament_level === 'tour_other' && baseCandidate(row),
  },
];

function groupBy(rows, keyFn) {
  const groups = new Map();
  for (const row of rows) {
    const key = keyFn(row);
    const group = groups.get(key) ?? [];
    group.push(row);
    groups.set(key, group);
  }
  return groups;
}

function summarizeBets(bets) {
  const total = bets.length;
  const wins = bets.filter((row) => row.won).length;
  const totalProfit = bets.reduce((sum, row) => sum + profit(row), 0);
  const staked = total * stakeUnits;
  const avgOdds = total ? bets.reduce((sum, row) => sum + row.bookmaker_odds, 0) / total : 0;
  const avgProbability = total ? bets.reduce((sum, row) => sum + row.model_probability, 0) / total : 0;
  const avgEv = total ? bets.reduce((sum, row) => sum + row.expected_value, 0) / total : 0;
  const avgEdge = total ? bets.reduce((sum, row) => sum + row.edge, 0) / total : 0;
  const avgConfidence = total ? bets.reduce((sum, row) => sum + row.confidence_score, 0) / total : 0;
  const avgBreakEven = total ? bets.reduce((sum, row) => sum + breakEvenPct(row), 0) / total : 0;

  return {
    bets: total,
    wins,
    losses: total - wins,
    hit_rate: total ? wins / total : 0,
    average_odds: avgOdds,
    average_break_even_rate: avgBreakEven,
    staked_units: staked,
    profit_units: totalProfit,
    roi_per_bet: staked ? totalProfit / staked : 0,
    average_model_probability: avgProbability,
    average_expected_value: avgEv,
    average_edge: avgEdge,
    average_confidence_score: avgConfidence,
    model_calibration_gap: total ? wins / total - avgProbability : 0,
    longest_losing_streak: longestLosingStreak(bets),
  };
}

function selectDaily(rows, threshold) {
  const selected = [];
  const byDay = groupBy(rows.filter((row) => row.confidence_score >= threshold), (row) => row.event_date);

  for (const [date, dayRows] of [...byDay.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
    const sorted = [...dayRows].sort((a, b) =>
      b.confidence_score - a.confidence_score
      || b.expected_value - a.expected_value
      || b.edge - a.edge
      || b.model_probability - a.model_probability
      || a.event_key.localeCompare(b.event_key));

    const usedMatches = new Set();
    let count = 0;
    for (const row of sorted) {
      if (onePickPerMatch && usedMatches.has(row.event_key)) continue;
      selected.push(row);
      usedMatches.add(row.event_key);
      count += 1;
      if (count >= maxPlaysPerDay) break;
    }
  }

  return selected;
}

function summarizeDaily(strategyId, threshold, selected) {
  const rows = [...groupBy(selected, (row) => row.event_date).entries()].map(([event_date, bets]) => ({
    strategy_id: strategyId,
    threshold,
    event_date,
    bets: bets.length,
    wins: bets.filter((row) => row.won).length,
    profit_units: bets.reduce((sum, row) => sum + profit(row), 0),
  })).sort((a, b) => a.event_date.localeCompare(b.event_date));

  return drawdownFromDaily(rows).curve;
}

function summarizeMonthly(strategyId, threshold, selected) {
  return [...groupBy(selected, (row) => row.event_date.slice(0, 7)).entries()].map(([month, bets]) => ({
    strategy_id: strategyId,
    threshold,
    month,
    ...summarizeBets(bets),
  })).sort((a, b) => a.month.localeCompare(b.month));
}

function buildBucketRows(strategyId, eligible) {
  return [...groupBy(eligible, (row) => confidenceBucket(row.confidence_score)).entries()].map(([confidence_bucket, bets]) => ({
    strategy_id: strategyId,
    confidence_bucket,
    confidence_min: Math.min(...bets.map((row) => row.confidence_score)),
    confidence_max: Math.max(...bets.map((row) => row.confidence_score)),
    ...summarizeBets(bets),
  })).sort((a, b) => String(a.confidence_bucket).localeCompare(String(b.confidence_bucket)));
}

function buildAuditSample(strategyId, selected) {
  const sorted = [...selected].sort((a, b) =>
    b.confidence_score - a.confidence_score
    || String(a.event_date).localeCompare(String(b.event_date))
    || a.event_key.localeCompare(b.event_key));
  return sorted.slice(0, auditSampleSize).map((row) => ({ ...row, strategy_id: strategyId }));
}

function escapeCsv(value) {
  return `"${String(value ?? '').replaceAll('"', '""')}"`;
}

function writeCsv(filePath, rows, columns) {
  const csv = [columns.join(','), ...rows.map((row) => columns.map((column) => escapeCsv(row[column])).join(','))].join('\n');
  fs.writeFileSync(filePath, csv);
}

function main() {
  const csvPaths = csvListRaw.split(',').map((item) => item.trim()).filter(Boolean);
  const rows = loadRows(csvPaths).filter((row) => modelModeFilter === 'any' || row.model_mode === modelModeFilter);
  const enrichedRows = rows.map((row) => {
    const confidence_score = confidenceScore(row);
    return {
      ...row,
      confidence_score,
      confidence_bucket: confidenceBucket(confidence_score),
      confidence_label: gradeLabel(confidence_score),
      suggested_stake_units: suggestedStakeUnits(confidence_score),
      volatility_label: volatilityLabel(row),
      profit_units: profit(row),
    };
  });

  fs.mkdirSync(outputDir, { recursive: true });

  const thresholds = [0, 60, 70, 80, 90];
  const bucketRows = [];
  const thresholdRows = [];
  const dailyRows = [];
  const monthlyRows = [];
  const betRows = [];
  const auditRows = [];

  for (const strategy of strategyPools) {
    const eligible = enrichedRows.filter(strategy.rule);
    bucketRows.push(...buildBucketRows(strategy.id, eligible));

    for (const threshold of thresholds) {
      const selected = selectDaily(eligible, threshold).map((row) => ({ ...row, strategy_id: strategy.id, threshold }));
      const daily = summarizeDaily(strategy.id, threshold, selected);
      const drawdown = drawdownFromDaily(daily);
      thresholdRows.push({
        strategy_id: strategy.id,
        threshold,
        ...summarizeBets(selected),
        max_drawdown_units: drawdown.max_drawdown_units,
        ending_bankroll: drawdown.ending_bankroll,
        positive_months: summarizeMonthly(strategy.id, threshold, selected).filter((row) => row.roi_per_bet > 0).length,
        total_months: summarizeMonthly(strategy.id, threshold, selected).length,
      });
      dailyRows.push(...daily);
      monthlyRows.push(...summarizeMonthly(strategy.id, threshold, selected));
      betRows.push(...selected);
      auditRows.push(...buildAuditSample(strategy.id, selected));
    }
  }

  const freezeManifest = {
    model_version: 'confidence_backtest_blind_v1',
    created_at: new Date().toISOString(),
    csv_paths: csvPaths,
    settings: {
      model_mode_filter: modelModeFilter,
      max_plays_per_day: maxPlaysPerDay,
      stake_units: stakeUnits,
      bankroll_start: bankrollStart,
      one_pick_per_match: onePickPerMatch,
      block_tiebreak: blockTiebreak,
      min_probability: minProbability,
      min_expected_value: minExpectedValue,
      min_edge: minEdge,
    },
    confidence_formula: {
      base: 50,
      inputs: [
        'expected_value',
        'edge',
        'model_probability',
        'bookmaker_odds',
        'score_family',
        'tournament_level',
        'match_type',
        'setfox_passed_default',
        'surface',
      ],
      buckets: {
        '90_100': 'Quant Grade',
        '80_89': 'S Confidence',
        '70_79': 'A Confidence',
        '60_69': 'Watchlist',
        '00_59': 'Research Only',
      },
      warning: 'Confidence score is an internal quality score, not a probability guarantee.',
    },
    strategy_pools: strategyPools.map(({ id, label, description }) => ({ id, label, description })),
    limitations: [
      'Historical API-Tennis odds may not match live executable prices.',
      'This is a blind historical simulation, not a guarantee of future results.',
      'Higher confidence buckets must improve ROI or drawdown before live promotion.',
      'Do not market this as certainty or risk-free betting.',
    ],
  };

  const summary = {
    ...freezeManifest,
    data: {
      rows_loaded: rows.length,
      first_date: rows[0]?.event_date ?? null,
      last_date: rows.at(-1)?.event_date ?? null,
      unique_matches: new Set(rows.map((row) => row.event_key)).size,
    },
    threshold_summary: thresholdRows,
    bucket_summary: bucketRows,
  };

  fs.writeFileSync(path.join(outputDir, 'confidence-summary.json'), JSON.stringify(summary, null, 2));
  fs.writeFileSync(path.join(outputDir, 'confidence-freeze-manifest.json'), JSON.stringify(freezeManifest, null, 2));

  writeCsv(path.join(outputDir, 'confidence-buckets.csv'), bucketRows, [
    'strategy_id', 'confidence_bucket', 'confidence_min', 'confidence_max', 'bets', 'wins', 'losses', 'hit_rate', 'average_odds', 'average_break_even_rate', 'staked_units', 'profit_units', 'roi_per_bet', 'average_model_probability', 'average_expected_value', 'average_edge', 'average_confidence_score', 'model_calibration_gap', 'longest_losing_streak',
  ]);

  writeCsv(path.join(outputDir, 'confidence-thresholds.csv'), thresholdRows, [
    'strategy_id', 'threshold', 'bets', 'wins', 'losses', 'hit_rate', 'average_odds', 'average_break_even_rate', 'staked_units', 'profit_units', 'roi_per_bet', 'average_model_probability', 'average_expected_value', 'average_edge', 'average_confidence_score', 'model_calibration_gap', 'longest_losing_streak', 'max_drawdown_units', 'ending_bankroll', 'positive_months', 'total_months',
  ]);

  writeCsv(path.join(outputDir, 'confidence-daily.csv'), dailyRows, [
    'strategy_id', 'threshold', 'event_date', 'bets', 'wins', 'profit_units', 'bankroll', 'drawdown_units',
  ]);

  writeCsv(path.join(outputDir, 'confidence-monthly.csv'), monthlyRows, [
    'strategy_id', 'threshold', 'month', 'bets', 'wins', 'losses', 'hit_rate', 'average_odds', 'average_break_even_rate', 'staked_units', 'profit_units', 'roi_per_bet', 'average_model_probability', 'average_expected_value', 'average_edge', 'average_confidence_score', 'model_calibration_gap', 'longest_losing_streak',
  ]);

  writeCsv(path.join(outputDir, 'confidence-bets.csv'), betRows, [
    'strategy_id', 'threshold', 'confidence_score', 'confidence_bucket', 'confidence_label', 'suggested_stake_units', 'volatility_label', 'model_mode', 'event_date', 'event_key', 'match', 'tournament', 'tournament_round', 'surface', 'tournament_level', 'match_type', 'score', 'score_family', 'odds_bucket', 'model_probability', 'bookmaker_odds', 'edge', 'expected_value', 'won', 'profit_units', 'setfox_passed_default',
  ]);

  writeCsv(path.join(outputDir, 'confidence-audit-samples.csv'), auditRows, [
    'strategy_id', 'threshold', 'confidence_score', 'confidence_bucket', 'confidence_label', 'model_mode', 'event_date', 'event_key', 'match', 'tournament', 'tournament_round', 'surface', 'tournament_level', 'match_type', 'score', 'score_family', 'odds_bucket', 'model_probability', 'bookmaker_odds', 'edge', 'expected_value', 'won', 'profit_units', 'setfox_passed_default',
  ]);

  console.log('SlipIQ Confidence Backtest V1 report:');
  console.log(JSON.stringify({ data: summary.data, threshold_summary: thresholdRows, outputDir }, null, 2));
  console.log(`Wrote confidence artifacts to ${outputDir}`);
}

main();
